CREATE TABLE IF NOT EXISTS ai_tool_catalog (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(id), tool_id varchar(255) NOT NULL, source varchar(32) NOT NULL, name varchar(128) NOT NULL, capability varchar(64) NOT NULL, summary text NOT NULL, tags_json jsonb NOT NULL DEFAULT '[]', risk varchar(16) NOT NULL, side_effect varchar(16) NOT NULL, schema_version integer NOT NULL, schema_hash varchar(64) NOT NULL, status varchar(16) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,tool_id));
CREATE TABLE IF NOT EXISTS ai_tool_search_documents (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(id), tool_id varchar(255) NOT NULL, search_text text NOT NULL, input_hints_json jsonb NOT NULL DEFAULT '[]', index_status varchar(16) NOT NULL CHECK(index_status IN ('pending','ready','failed','stale')), embedding_model varchar(128) NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,tool_id));
CREATE INDEX IF NOT EXISTS idx_ai_tool_search_fts ON ai_tool_search_documents USING gin(to_tsvector('simple',search_text));
CREATE TABLE IF NOT EXISTS ai_tool_scopes (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(id), user_id varchar(64) NOT NULL, realm varchar(16) NOT NULL, session_id varchar(64) NOT NULL, auth_version bigint NOT NULL, agent_run_id varchar(64), allowed_sources_json jsonb NOT NULL DEFAULT '[]', allowed_capabilities_json jsonb NOT NULL DEFAULT '[]', allowed_tools_json jsonb NOT NULL DEFAULT '[]', loaded_tools_json jsonb NOT NULL DEFAULT '[]', schema_bytes integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_ai_tool_scopes_actor ON ai_tool_scopes(tenant_id,user_id,expires_at);
CREATE TABLE IF NOT EXISTS ai_tool_confirmations (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(id), user_id varchar(64) NOT NULL, scope_id varchar(64) NOT NULL REFERENCES ai_tool_scopes(id), tool_call_id varchar(128) NOT NULL, tool_id varchar(255) NOT NULL, schema_hash varchar(64) NOT NULL, arguments_hash varchar(64) NOT NULL, arguments_json jsonb NOT NULL, arguments_summary_json jsonb NOT NULL, risk varchar(16) NOT NULL, side_effect varchar(16) NOT NULL, status varchar(16) NOT NULL CHECK(status IN ('pending','approved','rejected','expired','consumed','cancelled')), expires_at timestamptz NOT NULL, decided_at timestamptz, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_ai_tool_confirmations_actor_status ON ai_tool_confirmations(tenant_id,user_id,status);
ALTER TABLE ai_tool_confirmations ADD COLUMN IF NOT EXISTS invocation_id varchar(64) NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS ai_tool_invocations (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(id), user_id varchar(64) NOT NULL, scope_id varchar(64) NOT NULL REFERENCES ai_tool_scopes(id), agent_run_id varchar(64), tool_call_id varchar(128) NOT NULL, tool_id varchar(255) NOT NULL, source varchar(32) NOT NULL, target_action varchar(255) NOT NULL DEFAULT '', risk varchar(16) NOT NULL, side_effect varchar(16) NOT NULL, status varchar(24) NOT NULL CHECK(status IN ('running','waiting_confirmation','completed','failed','cancelled')), started_at timestamptz NOT NULL, finished_at timestamptz, duration_ms bigint, confirmation_id varchar(64), error_category varchar(64) NOT NULL DEFAULT '', request_id varchar(64) NOT NULL DEFAULT '', trace_id varchar(64) NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_ai_tool_invocations_actor_started ON ai_tool_invocations(tenant_id,user_id,started_at DESC);
